using System.Text;
namespace AiCare.Api;
internal sealed record InvoicePdfData(string Number,DateOnly InvoiceDate,DateOnly DueDate,string Status,string Provider,string ProviderAddress,string ProviderEmail,string ProviderPhone,string CompanyNumber,string VatNumber,string Customer,string CustomerAddress,string Funder,string Terms,string Remittance,string Currency,decimal Net,decimal VatRate,decimal Vat,decimal Gross,decimal Paid,decimal Credits,string Exemption,IReadOnlyList<InvoicePdfLine> Lines,string? CareRecipient=null,decimal WriteOffs=0,string? CurrencySymbol=null,string TaxLabel="VAT",string VatRoundingPolicy="Early");
internal sealed record InvoicePdfLine(string Description,decimal Quantity,decimal Rate,decimal Amount,string? VatTreatment=null,decimal? VatRate=null,decimal? VatAmount=null);
internal static class InvoicePdfDocument
{
 internal static byte[] Create(InvoicePdfData x){var money=string.IsNullOrWhiteSpace(x.CurrencySymbol)?x.Currency:$"{x.CurrencySymbol} ({x.Currency})";var rows=new List<string>{$"INVOICE {x.Number}",$"Invoice date: {x.InvoiceDate:yyyy-MM-dd}    Due date: {x.DueDate:yyyy-MM-dd}","",$"FROM: {x.Provider}",x.ProviderAddress,$"Email: {x.ProviderEmail}  Phone: {x.ProviderPhone}",$"Company: {x.CompanyNumber}  {x.TaxLabel}: {x.VatNumber}","",$"BILL TO: {x.Customer}",x.CustomerAddress,$"Funder: {x.Funder}",x.CareRecipient is null ? "" : $"Care recipient: {x.CareRecipient}","","DESCRIPTION                               QTY         RATE       AMOUNT"};foreach(var l in x.Lines){rows.Add($"{l.Description,-32} {l.Quantity,12:0.########} {l.Rate,12:0.0000} {l.Amount,12:0.00}");if(l.VatTreatment is not null)rows.Add($"{x.TaxLabel}: {l.VatTreatment} {l.VatRate:0.####}% - {money} {l.VatAmount:0.00}");}rows.AddRange(["",$"Net: {money} {x.Net:0.00}",$"{x.TaxLabel} total ({x.VatRoundingPolicy.ToLowerInvariant()} rounding): {money} {x.Vat:0.00}",$"TOTAL: {money} {x.Gross:0.00}","",x.Terms,$"{x.TaxLabel} note: {x.Exemption}","Remittance:",x.Remittance]);return Pdf(rows);}
 private static string Cut(string value,int n)=>value.Length<=n?value:value[..n];
 private static byte[] Pdf(IEnumerable<string> values)=>FinanceExportDocument.Pdf("Invoice",["Document"],values.Select(v=>new object?[]{v}).ToArray());
 private static IEnumerable<string> Wrap(string s,int n){if(s.Length==0){yield return "";yield break;}for(var i=0;i<s.Length;i+=n)yield return s.Substring(i,Math.Min(n,s.Length-i));}
}
